126	    /** Insert a new claim (assigning its id) or update an existing one. */
127	    public void save(Claim claim) {
128	        if (claim.getId() != null) {
129	            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ?, deferred_until = ?, proofs = ?, proof_photos = ?, locked_by = ?, ref = ?, tags = ?, tags_used = ?, void_reason = ?, edited_by = ?, batch = ? WHERE id = ?",
130	                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
131	                    claim.getNumber(), claim.getDue(), claim.getOpenedBy(), claim.isStated(), claim.getStatedDue(), claim.getCorrects(),
132	                    claim.getDeferredUntil() != null ? Date.valueOf(claim.getDeferredUntil()) : null, claim.getProofs(), claim.getProofPhotos(), claim.getLockedBy(), claim.getRef(), claim.getTags(), claim.getTagsUsed(), claim.getVoidReason(), claim.getEditedBy(), claim.getBatch(), claim.getId());
133	            return;
134	        }
135	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
136	        jdbc.update(con -> {
137	            PreparedStatement ps = con.prepareStatement(
138	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, due_by, number, opened_by, split_from, late_entry, ref, tags, tags_used, due_terms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
139	                    new String[] { "id" });
140	            ps.setString(1, claim.getSheetId());
141	            ps.setLong(2, claim.getPersonId());
142	            ps.setBigDecimal(3, claim.getAmount());
143	            ps.setDate(4, Date.valueOf(claim.getDate()));
144	            ps.setString(5, claim.getNote());
145	            ps.setString(6, claim.getStatus().name());
146	            ps.setString(7, claim.getCorrects());
147	            ps.setDate(8, Date.valueOf(claim.getDueBy()));
148	            ps.setString(9, claim.getNumber());
149	            ps.setString(10, claim.getOpenedBy());
150	            ps.setString(11, claim.getSplitFrom());
151	            ps.setBoolean(12, claim.isLateEntry());
152	            ps.setString(13, claim.getRef());
153	            ps.setString(14, claim.getTags());
154	            ps.setString(15, claim.getTagsUsed());
155	            ps.setObject(16, claim.getDueTerms(), Types.INTEGER);
156	            return ps;
157	        }, keys);
158	        claim.setId(keys.getKey().longValue());
159	    }
