161	    private static Claim claim(ResultSet rs, int i) throws SQLException {
162	        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
163	                rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
164	                ClaimStatus.valueOf(rs.getString("status")), rs.getString("number"),
165	                rs.getBigDecimal("due"), rs.getString("opened_by"));
