178	        claim.setVoidReason(rs.getString("void_reason"));
179	        claim.setEditedBy(rs.getString("edited_by"));
180	        int terms = rs.getInt("due_terms");
181	        claim.setDueTerms(rs.wasNull() ? null : terms);
182	        int batch = rs.getInt("batch");
183	        claim.setBatch(rs.wasNull() ? null : batch);
184	        long addedSeq = rs.getLong("added_seq");
