434	            "POOL", "POOL_MEMBER", "CREW", "CREW_MEMBER", "PLAN", "PLAN_CLAIM", "PLAN_PAUSE", "PLAN_CHANGE", "CLAIM_LINE", "PERSON_SNAPSHOT", "SHEET_NOTE",
435	            "PERIOD_POOL_CUT");
436	
437	    private final JdbcTemplate jdbc;
438	    private final TransactionTemplate transactions;
439	    private final Map<String, List<String>> columns = new HashMap<>();
440	    private final Rates rates;
441	
442	    public AsOf(JdbcTemplate jdbc, PlatformTransactionManager transactionManager, Rates rates) {
443	        this.jdbc = jdbc;
444	        this.rates = rates;
445	        this.transactions = new TransactionTemplate(transactionManager);
446	    }
447	
448	    /** Run `work` against the sheet as it stood at the end of `date`. It runs in a transaction of its
449	     *  own, on one connection, which is rolled back: the rebuilt rows are never kept. */
450	    public <T> T at(String sheetId, LocalDate date, Supplier<T> work) {
451	        return transactions.execute(status -> {
452	            status.setRollbackOnly();
453	            // One rebuild of the sheet at a time.
454	            jdbc.query("SELECT id FROM PUBLIC.sheet WHERE id = ? FOR UPDATE", (RowCallbackHandler) rs -> {}, sheetId);
455	            rebuild(sheetId, date);
456	            schema("ASOF");
457	            try {
458	                return work.get();
459	            } finally {
460	                schema("PUBLIC");
461	            }
462	        });
463	    }
464	
465	    /** What a screen reads: `work` on the sheet as it stood at the end of the as-of date given (see
466	     *  {@link #at}), or on the live sheet when none is given. Refused: an as-of that is not a date. */
467	    public <T> T view(String sheetId, String asOfText, Supplier<T> work) throws InvalidSheetRequestException {
468	        if (asOfText == null || asOfText.isBlank()) return work.get();
469	        LocalDate date;
470	        try {
471	            date = LocalDate.parse(asOfText.trim());
472	        } catch (DateTimeParseException e) {
473	            throw new InvalidSheetRequestException("Not a date: " + asOfText);
474	        }
475	        return at(sheetId, date, work);
476	    }
477	
478	    private void rebuild(String sheetId, LocalDate date) {
479	        jdbc.update("DELETE FROM ASOF.sheet WHERE id = ?", sheetId);
480	        jdbc.update("INSERT INTO ASOF.sheet SELECT * FROM PUBLIC.sheet WHERE id = ?", sheetId);
481	        // Archived only by an archive made by then.
482	        jdbc.update("UPDATE ASOF.sheet SET today = ?, archived = archived AND (archived_on IS NULL OR archived_on <= ?) "
483	                + "WHERE id = ?", Date.valueOf(date), Date.valueOf(date), sheetId);
484	        for (String table : TABLES) {
485	            List<String> cols = columns(table);
486	            String names = '"' + String.join("\", \"", cols) + '"';
487	            // The rows as they stood: each change made by then removes or adds one, in the order made.
488	            Map<List<Object>, Integer> rows = new LinkedHashMap<>();
489	            jdbc.query("SELECT " + names + ", H_OP FROM ASOF_HIST.\"" + table + "\" WHERE sheet_id = ? "
490	                    + "AND (H_MADE_ON IS NULL OR H_MADE_ON <= ?) ORDER BY H_SEQ", (RowCallbackHandler) rs -> {
491	                        List<Object> row = new ArrayList<>(cols.size());
492	                        for (int i = 1; i <= cols.size(); i++) row.add(rs.getObject(i));
493	                        rows.merge(row, "I".equals(rs.getString(cols.size() + 1)) ? 1 : -1, Integer::sum);
494	                    }, sheetId, Date.valueOf(date));
495	            // A snapshot of a day is written as the day is left: it is not part of the sheet at the end of it.
496	            if (table.equals("PERSON_SNAPSHOT")) {
497	                int leftDay = cols.indexOf("LEFT_DAY");
498	                rows.keySet().removeIf(row -> {
499	                    Object left = row.get(leftDay);
500	                    LocalDate day = left instanceof Date d ? d.toLocalDate() : (LocalDate) left;
501	                    return !day.isBefore(date);
502	                });
503	            }
504	            jdbc.update("DELETE FROM ASOF.\"" + table + "\" WHERE sheet_id = ?", sheetId);
505	            String insert = "INSERT INTO ASOF.\"" + table + "\" (" + names + ") VALUES ("
506	                    + "?, ".repeat(cols.size() - 1) + "?)";
507	            List<Object[]> batch = new ArrayList<>();
508	            rows.forEach((row, n) -> {
509	                for (int i = 0; i < n; i++) batch.add(row.toArray());
510	            });
511	            if (!batch.isEmpty()) jdbc.batchUpdate(insert, batch);
512	        }
513	        ancestors(sheetId);
514	    }
515	
516	    /** The tables an ancestor sheet lends the sheet: its rates (a grade with none on the sheet takes
517	     *  theirs) and its settings (naming its own parent). */
518	    private static final List<String> ANCESTOR_TABLES = List.of("RATE", "RATE_VERSION", "SHEET_SETTING");
519	
520	    /** The sheets of the sheet's rate lineage (see {@link Rates#lineage}): its parent sheets and the sheet
521	     *  it was cloned from, as they stand now: each keeps a today of its own, so only the sheet itself is
522	     *  rebuilt as of the date. */
523	    private void ancestors(String sheetId) {
524	        for (String sheet : rates.lineage(sheetId, parentIn("ASOF", sheetId))) {
525	            for (String table : ANCESTOR_TABLES) {
526	                String names = '"' + String.join("\", \"", columns(table)) + '"';
527	                jdbc.update("DELETE FROM ASOF.\"" + table + "\" WHERE sheet_id = ?", sheet);
528	                jdbc.update("INSERT INTO ASOF.\"" + table + "\" (" + names + ") SELECT " + names
529	                        + " FROM PUBLIC.\"" + table + "\" WHERE sheet_id = ?", sheet);
530	            }
531	        }
532	    }
533	
534	    private String parentIn(String schema, String sheetId) {
535	        return jdbc.query("SELECT parent_id FROM " + schema + ".sheet_setting WHERE sheet_id = ?",
536	                (rs, i) -> rs.getString(1), sheetId).stream().filter(p -> p != null).findFirst().orElse(null);
537	    }
538	
539	    private List<String> columns(String table) {
540	        synchronized (columns) {
541	            return columns.computeIfAbsent(table, t -> jdbc.queryForList("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS "
542	                    + "WHERE TABLE_SCHEMA = 'ASOF' AND TABLE_NAME = ? ORDER BY ORDINAL_POSITION", String.class, t));
543	        }
544	    }
545	
546	    private void schema(String schema) {
547	        jdbc.execute((ConnectionCallback<Void>) (Connection c) -> {
548	            c.setSchema(schema);
549	            return null;
550	        });
551	    }
552	}
553	package net.officefloor.hq.app.sheet;
554	
555	import java.sql.Connection;
556	import java.sql.PreparedStatement;
557	import java.sql.ResultSet;
558	import java.sql.SQLException;
559	import java.util.ArrayList;
560	import java.util.Arrays;
561	import java.util.List;
562	import org.h2.api.Trigger;
563	
564	/** The H2 trigger that keeps a table's change history in asof_hist: each change to a row writes the
565	 *  row it removed ('D') and the row it added ('I'), with the sheet's today when it was made. An
566	 *  update that changes nothing writes nothing. See {@link AsOf}. */
567	public class History implements Trigger {
568	
569	    private int sheetColumn;
570	    private String insert;
571	
572	    @Override
573	    public void init(Connection conn, String schemaName, String triggerName, String tableName, boolean before, int type)
574	            throws SQLException {
575	        List<String> columns = columns(conn, schemaName, tableName);
576	        sheetColumn = columns.indexOf("SHEET_ID");
577	        StringBuilder names = new StringBuilder();
578	        StringBuilder marks = new StringBuilder();
579	        for (String column : columns) {
580	            names.append('"').append(column).append("\", ");
581	            marks.append("?, ");
582	        }
583	        insert = "INSERT INTO ASOF_HIST.\"" + tableName + "\" (" + names + "H_SEQ, H_MADE_ON, H_OP) VALUES ("
584	                + marks + "NEXT VALUE FOR ASOF_HIST.CHANGE_SEQ, "
585	                + "(SELECT today FROM PUBLIC.sheet WHERE id = ?), ?)";
586	    }
587	
588	    @Override
589	    public void fire(Connection conn, Object[] oldRow, Object[] newRow) throws SQLException {
590	        if (oldRow != null && newRow != null && Arrays.equals(oldRow, newRow)) return;
591	        if (oldRow != null) write(conn, oldRow, "D");
592	        if (newRow != null) write(conn, newRow, "I");
593	    }
594	
595	    private void write(Connection conn, Object[] row, String op) throws SQLException {
596	        try (PreparedStatement ps = conn.prepareStatement(insert)) {
597	            int i = 1;
598	            for (Object value : row) ps.setObject(i++, value);
599	            ps.setObject(i++, row[sheetColumn]);
600	            ps.setString(i, op);
601	            ps.executeUpdate();
602	        }
603	    }
604	
605	    /** The table's column names, in order. */
606	    static List<String> columns(Connection conn, String schema, String table) throws SQLException {
607	        List<String> columns = new ArrayList<>();
608	        try (PreparedStatement ps = conn.prepareStatement("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS "
609	                + "WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ? ORDER BY ORDINAL_POSITION")) {
610	            ps.setString(1, schema);
611	            ps.setString(2, table);
612	            try (ResultSet rs = ps.executeQuery()) {
613	                while (rs.next()) columns.add(rs.getString(1));
614	            }
615	        }
616	        return columns;
617	    }
618	}
