/** A claim as the screen sees it: the amount with two decimals, the date as yyyy-mm-dd,
 *  the status as DRAFT, OPEN, PENDING, SETTLED or VOID, the number null when the claim has none, the due
 *  fixed at settling with two decimals, null when it has none (its due is worked out live),
 *  who opened it, null while it has not been opened, whether its person's last statement binds it
 *  and the figure it binds it to (two decimals; null when unbound or bound to n/a), and the number
 *  of the claim a correction corrects (null when it is not a correction), and whether its live
 *  figures round half up (else half to even), by the sheet's policy date, and the due-by fixed when it was added (yyyy-mm-dd), and its status log, oldest first (see {@link ClaimLog}),
 *  and whether it is deferred now and the date it was last deferred until (yyyy-mm-dd; null when it never was), and its proofs count and how many of them are receipts and photos, and the number of the claim it was split off (null when it was not), and the user whose open editor locks it (null when none), and whether it was added while its period was soft-closed, and the last day it was reminded (yyyy-mm-dd; null when it never was), and whether its late charge is waived, and whether it is held, and its external reference (null when none), and its tags (sorted, empty when none) and every tag it has ever carried, and the reason it was voided with (null when none), and its comments, oldest first (see {@link ClaimComments}), and its lines, in the order added (see {@link ClaimLines}), and the number of the bulk settle batch that settled it (null when none), and the sequence it was added in (see {@link Claim#seq}). */
public record ClaimResponse(long id, long personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated, String statedDue, String corrects, boolean halfUp, String dueBy, List<String> log,
        boolean deferred, String deferredUntil, int proofs, int proofReceipts, int proofPhotos, String splitFrom, String lockedBy,
        boolean lateEntry, String remindedOn, boolean waived, boolean held, String ref, List<String> tags, List<String> tagsUsed, String voidReason, List<String> comments, List<String> lines, Integer batch, Long seq) {
    public static ClaimResponse from(Claim claim, Figures figures, List<String> log, List<String> comments, List<String> lines) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getDue() != null ? claim.getDue().toPlainString() : null, claim.getOpenedBy(),
                claim.isStated(), claim.getStatedDue() != null ? claim.getStatedDue().toPlainString() : null,
                claim.getCorrects(), figures.rounding(claim) == RoundingMode.HALF_UP,
                claim.getDueBy().toString(), log, claim.isDeferred(),
                claim.getDeferredUntil() != null ? claim.getDeferredUntil().toString() : null, claim.getProofs(), claim.proofsOf(ProofKind.RECEIPT), claim.getProofPhotos(), claim.getSplitFrom(), claim.getLockedBy(),
                claim.isLateEntry(), claim.getRemindedOn() != null ? claim.getRemindedOn().toString() : null, claim.isWaived(), claim.isHeld(), claim.getRef(),
                split(claim.getTags()), split(claim.getTagsUsed()), claim.getVoidReason(), comments, lines, claim.getBatch(), claim.seq());
    }

    private static List<String> split(String tags) {
        return tags == null ? List.of() : List.of(tags.split(","));
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Connection;
import java.sql.Date;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import net.officefloor.hq.app.rate.Rates;
import org.springframework.jdbc.core.ConnectionCallback;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** A sheet as it stood at the end of a date: every change made while the sheet's today was on or
 *  before that date counts, every later change does not, and that date stands in for the sheet's
 *  today. The sheet's rows are rebuilt from the change history (see {@link History}) into the asof
 *  schema, and the work runs against it in place of the live tables, so every rule reads the sheet
 *  as it was. The work must only read: what it writes is thrown away. */
@Service
public class AsOf {

    /** The tables of a sheet's data (keyed by sheet_id) kept in asof_hist and rebuilt into asof. */
    static final List<String> TABLES = List.of("CLAIM", "PERSON", "PERSON_GRADE", "PERSON_HOLD", "PERSON_PATRON",
            "PERSON_WATCH", "PERSON_STATEMENT", "PERIOD", "PERIOD_PERSON_TOTAL", "PERIOD_NUMBER", "RATE", "RATE_VERSION",
            "SHEET_SETTING", "SHEET_SETTING_DATED", "SHEET_ROLE", "SHEET_PERMISSION", "SHEET_DELEGATION",
            "CLAIM_LOG", "SHEET_GRADE_TERMS", "SHEET_HOLIDAY", "SHEET_VOID_REASON", "CLAIM_COMMENT", "PERSON_ALIAS",
            "POOL", "POOL_MEMBER", "CREW", "CREW_MEMBER", "PLAN", "PLAN_CLAIM", "PLAN_PAUSE", "PLAN_CHANGE", "CLAIM_LINE", "PERSON_SNAPSHOT", "SHEET_NOTE",
            "PERIOD_POOL_CUT");

    private final JdbcTemplate jdbc;
    private final TransactionTemplate transactions;
    private final Map<String, List<String>> columns = new HashMap<>();
    private final Rates rates;

    public AsOf(JdbcTemplate jdbc, PlatformTransactionManager transactionManager, Rates rates) {
        this.jdbc = jdbc;
        this.rates = rates;
        this.transactions = new TransactionTemplate(transactionManager);
    }

    /** Run `work` against the sheet as it stood at the end of `date`. It runs in a transaction of its
     *  own, on one connection, which is rolled back: the rebuilt rows are never kept. */
    public <T> T at(String sheetId, LocalDate date, Supplier<T> work) {
        return transactions.execute(status -> {
            status.setRollbackOnly();
            // One rebuild of the sheet at a time.
            jdbc.query("SELECT id FROM PUBLIC.sheet WHERE id = ? FOR UPDATE", (RowCallbackHandler) rs -> {}, sheetId);
            rebuild(sheetId, date);
            schema("ASOF");
            try {
                return work.get();
            } finally {
                schema("PUBLIC");
            }
        });
    }

    /** What a screen reads: `work` on the sheet as it stood at the end of the as-of date given (see
     *  {@link #at}), or on the live sheet when none is given. Refused: an as-of that is not a date. */
    public <T> T view(String sheetId, String asOfText, Supplier<T> work) throws InvalidSheetRequestException {
        if (asOfText == null || asOfText.isBlank()) return work.get();
        LocalDate date;
        try {
            date = LocalDate.parse(asOfText.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date: " + asOfText);
        }
        return at(sheetId, date, work);
    }

    private void rebuild(String sheetId, LocalDate date) {
        jdbc.update("DELETE FROM ASOF.sheet WHERE id = ?", sheetId);
        jdbc.update("INSERT INTO ASOF.sheet SELECT * FROM PUBLIC.sheet WHERE id = ?", sheetId);
        // Archived only by an archive made by then.
        jdbc.update("UPDATE ASOF.sheet SET today = ?, archived = archived AND (archived_on IS NULL OR archived_on <= ?) "
                + "WHERE id = ?", Date.valueOf(date), Date.valueOf(date), sheetId);
        for (String table : TABLES) {
            List<String> cols = columns(table);
            String names = '"' + String.join("\", \"", cols) + '"';
            // The rows as they stood: each change made by then removes or adds one, in the order made.
            Map<List<Object>, Integer> rows = new LinkedHashMap<>();
            jdbc.query("SELECT " + names + ", H_OP FROM ASOF_HIST.\"" + table + "\" WHERE sheet_id = ? "
                    + "AND (H_MADE_ON IS NULL OR H_MADE_ON <= ?) ORDER BY H_SEQ", (RowCallbackHandler) rs -> {
                        List<Object> row = new ArrayList<>(cols.size());
                        for (int i = 1; i <= cols.size(); i++) row.add(rs.getObject(i));
                        rows.merge(row, "I".equals(rs.getString(cols.size() + 1)) ? 1 : -1, Integer::sum);
                    }, sheetId, Date.valueOf(date));
            // A snapshot of a day is written as the day is left: it is not part of the sheet at the end of it.
            if (table.equals("PERSON_SNAPSHOT")) {
                int leftDay = cols.indexOf("LEFT_DAY");
                rows.keySet().removeIf(row -> {
                    Object left = row.get(leftDay);
                    LocalDate day = left instanceof Date d ? d.toLocalDate() : (LocalDate) left;
                    return !day.isBefore(date);
                });
            }
            jdbc.update("DELETE FROM ASOF.\"" + table + "\" WHERE sheet_id = ?", sheetId);
            String insert = "INSERT INTO ASOF.\"" + table + "\" (" + names + ") VALUES ("
                    + "?, ".repeat(cols.size() - 1) + "?)";
            List<Object[]> batch = new ArrayList<>();
            rows.forEach((row, n) -> {
                for (int i = 0; i < n; i++) batch.add(row.toArray());
            });
            if (!batch.isEmpty()) jdbc.batchUpdate(insert, batch);
        }
        ancestors(sheetId);
    }

    /** The tables an ancestor sheet lends the sheet: its rates (a grade with none on the sheet takes
     *  theirs) and its settings (naming its own parent). */
    private static final List<String> ANCESTOR_TABLES = List.of("RATE", "RATE_VERSION", "SHEET_SETTING");

    /** The sheets of the sheet's rate lineage (see {@link Rates#lineage}): its parent sheets and the sheet
     *  it was cloned from, as they stand now: each keeps a today of its own, so only the sheet itself is
     *  rebuilt as of the date. */
    private void ancestors(String sheetId) {
        for (String sheet : rates.lineage(sheetId, parentIn("ASOF", sheetId))) {
            for (String table : ANCESTOR_TABLES) {
                String names = '"' + String.join("\", \"", columns(table)) + '"';
                jdbc.update("DELETE FROM ASOF.\"" + table + "\" WHERE sheet_id = ?", sheet);
                jdbc.update("INSERT INTO ASOF.\"" + table + "\" (" + names + ") SELECT " + names
                        + " FROM PUBLIC.\"" + table + "\" WHERE sheet_id = ?", sheet);
            }
        }
    }

    private String parentIn(String schema, String sheetId) {
        return jdbc.query("SELECT parent_id FROM " + schema + ".sheet_setting WHERE sheet_id = ?",
                (rs, i) -> rs.getString(1), sheetId).stream().filter(p -> p != null).findFirst().orElse(null);
    }

    private List<String> columns(String table) {
        synchronized (columns) {
            return columns.computeIfAbsent(table, t -> jdbc.queryForList("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS "
                    + "WHERE TABLE_SCHEMA = 'ASOF' AND TABLE_NAME = ? ORDER BY ORDINAL_POSITION", String.class, t));
        }
    }

    private void schema(String schema) {
        jdbc.execute((ConnectionCallback<Void>) (Connection c) -> {
            c.setSchema(schema);
            return null;
        });
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.h2.api.Trigger;

/** The H2 trigger that keeps a table's change history in asof_hist: each change to a row writes the
 *  row it removed ('D') and the row it added ('I'), with the sheet's today when it was made. An
 *  update that changes nothing writes nothing. See {@link AsOf}. */
public class History implements Trigger {

    private int sheetColumn;
    private String insert;

    @Override
    public void init(Connection conn, String schemaName, String triggerName, String tableName, boolean before, int type)
            throws SQLException {
        List<String> columns = columns(conn, schemaName, tableName);
        sheetColumn = columns.indexOf("SHEET_ID");
        StringBuilder names = new StringBuilder();
        StringBuilder marks = new StringBuilder();
        for (String column : columns) {
            names.append('"').append(column).append("\", ");
            marks.append("?, ");
        }
        insert = "INSERT INTO ASOF_HIST.\"" + tableName + "\" (" + names + "H_SEQ, H_MADE_ON, H_OP) VALUES ("
                + marks + "NEXT VALUE FOR ASOF_HIST.CHANGE_SEQ, "
                + "(SELECT today FROM PUBLIC.sheet WHERE id = ?), ?)";
    }

    @Override
    public void fire(Connection conn, Object[] oldRow, Object[] newRow) throws SQLException {
        if (oldRow != null && newRow != null && Arrays.equals(oldRow, newRow)) return;
        if (oldRow != null) write(conn, oldRow, "D");
        if (newRow != null) write(conn, newRow, "I");
    }

    private void write(Connection conn, Object[] row, String op) throws SQLException {
        try (PreparedStatement ps = conn.prepareStatement(insert)) {
            int i = 1;
            for (Object value : row) ps.setObject(i++, value);
            ps.setObject(i++, row[sheetColumn]);
            ps.setString(i, op);
            ps.executeUpdate();
        }
    }

    /** The table's column names, in order. */
    static List<String> columns(Connection conn, String schema, String table) throws SQLException {
        List<String> columns = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS "
                + "WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ? ORDER BY ORDINAL_POSITION")) {
            ps.setString(1, schema);
            ps.setString(2, table);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) columns.add(rs.getString(1));
            }
        }
        return columns;
    }
}

