package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Holds an OPEN or PENDING claim, or releases a held one. Refused: a claim in any other status. */
public class ApplyClaimHold {
    public void apply(@Val ClaimHold change, @Val Claim claim) throws ClaimStatusRefusedException {
        if (!claim.getStatus().isOpen()) {
            throw new ClaimStatusRefusedException("Only an OPEN or PENDING claim can be held or released");
        }
        claim.setHeld(!claim.isHeld());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaimHold {
    public void validate(@RequestBody ClaimHoldRequest request, Out<ClaimHold> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        if (user.isEmpty()) throw new InvalidSheetRequestException("Who holds the claim must be named");
        actor.set(new Actor(user));
        body.set(new ClaimHold(user));
    }
}
package net.officefloor.hq.app.claim;

/** Body of holding or releasing a claim: who toggles it. */
public record ClaimHoldRequest(String user) {
}
# Hold an OPEN or PENDING claim, or release a held one: while held it counts in no live total,
# unless a statement binds it. A claim in any other status is a 409 and writes nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimHold
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimHold
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimHeld
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused hold writes no line.
record:
  class: net.officefloor.hq.app.claim.RecordClaimHeld
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
